(() => {
  'use strict';
  const svgNS = 'http://www.w3.org/2000/svg';
  const rowLengths = Array.from({ length: 15 }, (_, r) => r % 2 === 0 ? 8 : 7);
  const names = { haplos: 'Haplós', kleido: 'Kleido', hipeus: 'Hipeus', peus: 'Peus', pyrgos: 'Pyrgos', thyra: 'Thyra', toxot: 'Toxot', anax: 'Anax', basileus: 'Basileo' };
  const marks = { haplos: 'H', kleido: 'K', hipeus: 'I', peus: 'P', pyrgos: 'R', thyra: 'T', toxot: 'X', anax: 'A', basileus: 'B' };
  const board = document.querySelector('#board');
  const state = { pieces: [], turn: 'white', selected: null, targets: [], history: [], snapshots: [], repetitions: new Map(), reserve: { white: 0, black: 0 }, gameOver: false, pendingPromotion: null };
  const $ = id => document.getElementById(id);
  const cellKey = (r, c) => `${r},${c}`;
  const findPiece = (r, c) => state.pieces.find(p => p.r === r && p.c === c);
  const rowCell = (r, c) => r >= 0 && r < 15 && c >= 0 && c < rowLengths[r];
  function addPiece(color, type, r, c, moved = false) { state.pieces.push({ id: `${color}-${type}-${r}-${c}-${Math.random().toString(36).slice(2, 7)}`, color, type, r, c, moved }); }
  function reset() {
    state.pieces = []; state.turn = 'white'; state.selected = null; state.targets = []; state.history = []; state.snapshots = []; state.repetitions.clear(); state.reserve = { white: 0, black: 0 }; state.gameOver = false;
    const back = ['pyrgos', 'thyra', 'toxot', 'basileus', 'anax', 'toxot', 'thyra', 'pyrgos'];
    back.forEach((type, c) => addPiece('black', type, 0, c));
    [0, 2, 4, 6].forEach(c => addPiece('black', 'kleido', 1, c)); [1, 5].forEach(c => addPiece('black', 'hipeus', 1, c));
    for (let c = 0; c < 8; c++) addPiece('black', 'haplos', 2, c);
    for (let c = 0; c < 8; c++) addPiece('white', 'haplos', 12, c);
    [0, 2, 4, 6].forEach(c => addPiece('white', 'kleido', 13, c)); [1, 5].forEach(c => addPiece('white', 'hipeus', 13, c));
    back.forEach((type, c) => addPiece('white', type, 14, c));
    pushPosition(); render(); setStatus('Elige una ficha para ver sus movimientos.');
  }
  function posSig() { return state.pieces.map(p => `${p.color[0]}${p.type[0]}${p.r}${p.c}`).sort().join('|') + `:${state.turn}:${state.reserve.white}${state.reserve.black}`; }
  function pushPosition() { const key = posSig(); state.snapshots.push(key); state.repetitions.set(key, (state.repetitions.get(key) || 0) + 1); }
  function setStatus(message) { $('status-message').innerHTML = message; }
  function cellCenter(r, c) { return { x: 80 + c * 80 + (8 - rowLengths[r]) * 40, y: 38 + r * 48.5 }; }
  function makeSvg(tag, attrs = {}) { const n = document.createElementNS(svgNS, tag); Object.entries(attrs).forEach(([k, v]) => n.setAttribute(k, v)); return n; }
  function render() {
    board.innerHTML = '';
    const defs = makeSvg('defs');
    const filter = makeSvg('filter', { id: 'shadow', x: '-60%', y: '-60%', width: '220%', height: '220%' });
    filter.append(makeSvg('feDropShadow', { dx: '0', dy: '3', stdDeviation: '2.5', 'flood-color': '#080e0f', 'flood-opacity': '.55' })); defs.append(filter);
    const grad = makeSvg('linearGradient', { id: 'white-piece', x1: '0', y1: '0', x2: '0', y2: '1' }); grad.append(makeSvg('stop', { offset: '0%', 'stop-color': '#f4f1e4' }), makeSvg('stop', { offset: '100%', 'stop-color': '#c6d0c0' })); defs.append(grad);
    const grad2 = makeSvg('linearGradient', { id: 'black-piece', x1: '0', y1: '0', x2: '0', y2: '1' }); grad2.append(makeSvg('stop', { offset: '0%', 'stop-color': '#687d79' }), makeSvg('stop', { offset: '100%', 'stop-color': '#304341' })); defs.append(grad2); board.append(defs);
    const cells = makeSvg('g');
    for (let r = 0; r < 15; r++) for (let c = 0; c < rowLengths[r]; c++) {
      const { x, y } = cellCenter(r, c), key = cellKey(r, c), sel = state.selected && state.selected.r === r && state.selected.c === c;
      const target = state.targets.some(t => t.r === r && t.c === c);
      const isBlackRow = r % 2 === 0;
      const fill = isBlackRow ? ((r + c) % 4 === 0 ? '#33494a' : '#2c4143') : ((r + c) % 4 === 1 ? '#394e4e' : '#34494a');
      const tile = makeSvg('polygon', { points: `${x},${y - 21} ${x + 38},${y} ${x},${y + 21} ${x - 38},${y}`, fill, stroke: '#52625e', 'stroke-width': '.8', class: `cell${sel ? ' selected' : ''}${target ? ' move-target' : ''}`, 'data-r': r, 'data-c': c, role: 'gridcell', tabindex: '0', 'aria-label': `Fila ${r + 1}, casilla ${c + 1}${findPiece(r, c) ? `, ${names[findPiece(r, c).type]} ${findPiece(r, c).color === 'white' ? 'blanca' : 'negra'}` : ''}` });
      cells.append(tile);
      if (target) {
        const occupied = findPiece(r, c); const dot = makeSvg(occupied ? 'circle' : 'circle', { cx: x, cy: y, r: occupied ? 17 : 5.2, fill: occupied ? 'none' : '#b3e4c4', stroke: occupied ? '#e5b878' : 'none', 'stroke-width': occupied ? 2 : 0, opacity: occupied ? '.9' : '.72', class: 'move-ring' }); cells.append(dot);
      }
      if (sel) cells.append(makeSvg('polygon', { points: `${x},${y - 21} ${x + 38},${y} ${x},${y + 21} ${x - 38},${y}`, fill: 'none', stroke: '#a9dfbf', 'stroke-width': '2.3', 'pointer-events': 'none' }));
    }
    board.append(cells);
    const piecesGroup = makeSvg('g');
    state.pieces.forEach(p => {
      const { x, y } = cellCenter(p.r, p.c), isWhite = p.color === 'white';
      const g = makeSvg('g', { class: 'piece-group', 'pointer-events': 'none' });
      g.append(makeSvg('circle', { cx: x, cy: y, r: '14.4', fill: isWhite ? 'url(#white-piece)' : 'url(#black-piece)', stroke: isWhite ? '#f5f2e7' : '#80918a', 'stroke-width': '1.2', class: 'piece-shadow' }));
      g.append(makeSvg('circle', { cx: x, cy: y, r: '10.7', fill: 'none', stroke: isWhite ? '#a8b8a8' : '#263635', 'stroke-width': '.7', opacity: '.85' }));
      const text = makeSvg('text', { x, y: y + .5, class: 'piece-label', fill: isWhite ? '#33433c' : '#eff0e5', 'font-size': p.type === 'basileus' ? '11' : '10.5' }); text.textContent = marks[p.type]; g.append(text);
      if (p.type === 'basileus') g.append(makeSvg('circle', { cx: x, cy: y, r: '17.5', fill: 'none', stroke: isWhite ? '#c2d4c3' : '#71827d', 'stroke-width': '.75', opacity: '.8' }));
      piecesGroup.append(g);
    });
    board.append(piecesGroup);
    $('turn-label').textContent = state.turn === 'white' ? 'BLANCAS' : 'NEGRAS'; $('turn-dot').style.background = state.turn === 'white' ? '#b7dec3' : '#748a84';
    $('move-number').textContent = String(Math.floor(state.history.length / 2) + 1).padStart(2, '0'); $('turn-index').textContent = String(Math.floor(state.history.length / 2) + 1).padStart(2, '0');
    $('player-name').textContent = state.turn === 'white' ? 'Blancas' : 'Negras'; $('player-subtitle').textContent = state.gameOver ? 'Partida finalizada' : 'Tu turno';
    const emblem = $('player-piece'); emblem.textContent = state.turn === 'white' ? 'W' : 'N'; emblem.classList.toggle('black', state.turn === 'black');
    $('white-count').textContent = state.pieces.filter(p => p.color === 'white').length; $('black-count').textContent = state.pieces.filter(p => p.color === 'black').length;
    $('undo-button').disabled = state.history.length === 0; $('game-state').textContent = state.gameOver ? 'FINALIZADA' : 'EN CURSO';
    $('history-count').textContent = `${state.history.length} ${state.history.length === 1 ? 'JUGADA' : 'JUGADAS'}`;
    renderHistory();
  }
  function rowNeighbors(r, c, dir) {
    const nr = r + dir; if (!rowCell(nr, 0)) return [];
    const x = c + (8 - rowLengths[r]) / 2, shift = (8 - rowLengths[nr]) / 2;
    return Array.from({ length: rowLengths[nr] }, (_, nc) => ({ r: nr, c: nc })).filter(n => Math.abs((n.c + shift) - x) <= .51);
  }
  function pathClear(from, to) {
    const dr = to.r - from.r, dc = to.c - from.c;
    if (!dr) { const step = Math.sign(dc); for (let c = from.c + step; c !== to.c; c += step) if (findPiece(from.r, c)) return false; return true; }
    if (Math.abs(dr) === 1) return true;
    const step = Math.sign(dr); let current = { r: from.r, c: from.c };
    for (let n = 0; n < Math.abs(dr) - 1; n++) {
      const next = rowNeighbors(current.r, current.c, step).sort((a, b) => Math.abs((a.c - current.c) - dc / dr) - Math.abs((b.c - current.c) - dc / dr))[0];
      if (!next) return false; current = next; if (findPiece(current.r, current.c)) return false;
    }
    return true;
  }
  function destinations(p) {
    const map = new Map(), add = (r, c, jump = false, ray = false) => {
      if (!rowCell(r, c) || (r === p.r && c === p.c)) return;
      const target = findPiece(r, c); if (target && target.color === p.color) return;
      if (!jump && !ray && Math.abs(r - p.r) > 1 && !pathClear(p, { r, c })) return;
      if (ray && !pathClear(p, { r, c })) return;
      map.set(cellKey(r, c), { r, c });
    };
    const fwd = p.color === 'white' ? -1 : 1;
    if (p.type === 'haplos') {
      rowNeighbors(p.r, p.c, fwd).forEach(n => { if (!findPiece(n.r, n.c)) add(n.r, n.c); });
      // Haplós can capture forward across a corner; its straight advance is never a capture.
      rowNeighbors(p.r, p.c, fwd).forEach(n => { if (findPiece(n.r, n.c)?.color !== p.color && findPiece(n.r, n.c)) add(n.r, n.c); });
      if (!p.moved) {
        const two = rowNeighbors(p.r, p.c, fwd).flatMap(n => rowNeighbors(n.r, n.c, fwd));
        two.forEach(n => { if (!findPiece(n.r, n.c) && pathClear(p, n)) add(n.r, n.c); });
      }
    } else if (p.type === 'hipeus' || p.type === 'peus') {
      const steps = [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]];
      for (const [dr, dc] of steps) for (let c = 0; c < rowLengths[p.r + dr]; c++) if (c - p.c === dc) add(p.r + dr, c, p.type === 'hipeus');
    } else if (p.type === 'kleido') {
      const steps = [[-2,-1],[-2,0],[-2,1],[2,-1],[2,0],[2,1],[-1,-2],[-1,2],[1,-2],[1,2],[0,-2],[0,2]];
      for (const [dr, dc] of steps) add(p.r + dr, p.c + dc, true);
    } else if (p.type === 'thyra' || p.type === 'basileus') {
      const max = p.type === 'basileus' ? 1 : 3;
      for (let dr = -max; dr <= max; dr++) for (let dc = -max; dc <= max; dc++) if ((dr || dc) && Math.max(Math.abs(dr), Math.abs(dc)) <= max) add(p.r + dr, p.c + dc, false, true);
    } else if (p.type === 'pyrgos' || p.type === 'toxot' || p.type === 'anax') {
      const directions = [];
      if (p.type !== 'toxot') directions.push([0, 1], [0, -1], [1, 0], [-1, 0]);
      if (p.type !== 'pyrgos') directions.push([1, 1], [1, -1], [-1, 1], [-1, -1]);
      for (const [dr, dc] of directions) {
        for (let dist = 1; dist < 15; dist++) {
          const r = p.r + dr * dist, c = p.c + dc * dist;
          if (!rowCell(r, c)) break;
          if (!pathClear(p, { r, c })) break;
          add(r, c, false, true); if (findPiece(r, c)) break;
        }
      }
    }
    return [...map.values()];
  }
  function allMoves(color) { return state.pieces.filter(p => p.color === color).some(p => destinations(p).length > 0); }
  function renderHistory() {
    const list = $('move-history'); list.innerHTML = '';
    if (!state.history.length) { const li = document.createElement('li'); li.className = 'empty-history'; li.textContent = 'La partida comienza aquí.'; list.append(li); return; }
    for (let i = 0; i < state.history.length; i += 2) {
      const li = document.createElement('li'); const n = document.createElement('span'); n.className = 'move-number'; n.textContent = `${String(Math.floor(i / 2) + 1).padStart(2, '0')}.`; li.append(n);
      for (const move of [state.history[i], state.history[i + 1]]) { const entry = document.createElement('span'); entry.className = 'move-entry'; entry.textContent = move ? `${move.color === 'white' ? '○' : '●'} ${move.text}` : ''; li.append(entry); }
      list.append(li);
    }
  }
  function selectPiece(p) { state.selected = { r: p.r, c: p.c }; state.targets = destinations(p); render(); setStatus(`Seleccionada: <b>${names[p.type]}</b>. Elige una casilla iluminada.`); }
  function attemptMove(r, c) {
    const piece = state.pieces.find(p => p.r === state.selected.r && p.c === state.selected.c); if (!piece) return;
    const target = state.targets.find(t => t.r === r && t.c === c); if (!target) return;
    const victim = findPiece(r, c); const capturedBasileus = victim?.type === 'basileus';
    if (victim) {
      state.pieces = state.pieces.filter(p => p.id !== victim.id);
      if (victim.type === 'hipeus') state.reserve[victim.color]++;
    }
    piece.r = r; piece.c = c; piece.moved = true;
    let moveText = `${names[piece.type]} ${String.fromCharCode(65 + c)}${15 - r}${victim ? ` × ${names[victim.type]}` : ''}`;
    state.history.push({ color: state.turn, text: moveText }); state.selected = null; state.targets = [];
    if (piece.type === 'haplos' && ((piece.color === 'white' && r === 0) || (piece.color === 'black' && r === 14))) {
      state.pendingPromotion = piece.id; render(); openPromotion(); return;
    }
    finishTurn(capturedBasileus);
  }
  function finishTurn(capturedBasileus = false) {
    state.turn = state.turn === 'white' ? 'black' : 'white'; pushPosition();
    if (capturedBasileus) { state.gameOver = true; render(); showToast(`${state.turn === 'white' ? 'Negras' : 'Blancas'} ganan: ¡basileo capturado!`); setStatus(`¡Victoria! ${state.turn === 'white' ? 'Negras' : 'Blancas'} capturan al basileo.`); return; }
    const sig = state.snapshots[state.snapshots.length - 1];
    if ((state.repetitions.get(sig) || 0) >= 3) { state.gameOver = true; render(); setStatus('Empate: la misma posición se repitió tres veces.'); showToast('Empate por repetición'); return; }
    render();
    if (!allMoves(state.turn)) { state.gameOver = true; render(); setStatus('Empate: el jugador al turno no tiene movimientos legales.'); showToast('Empate: sin movimientos'); return; }
    if (state.reserve[state.turn] > 0) setStatus(`Tienes un hipeus en reserva. <button class="inline-action" id="invoke-peus">Invocar peus</button>`);
    else setStatus(`${state.turn === 'white' ? 'Blancas' : 'Negras'} al turno. Elige una ficha.`);
  }
  function openPromotion() {
    const modal = $('promotion-modal'), choices = $('promotion-options'); choices.innerHTML = '';
    ['pyrgos', 'thyra', 'toxot', 'anax', 'basileus', 'kleido', 'peus'].forEach(type => {
      const b = document.createElement('button'); b.className = 'promotion-choice'; b.innerHTML = `<strong>${marks[type]}</strong><small>${names[type]}</small>`; b.addEventListener('click', () => {
        const p = state.pieces.find(x => x.id === state.pendingPromotion); if (!p) return;
        p.type = type; state.history[state.history.length - 1].text = `${names[type]} (ascenso)`; state.pendingPromotion = null; modal.hidden = true; finishTurn();
      }); choices.append(b);
    }); modal.hidden = false;
  }
  function invokePeus() {
    if (state.gameOver || !state.reserve[state.turn]) return;
    const r = state.turn === 'white' ? 13 : 1, c = Math.floor(rowLengths[r] / 2);
    if (findPiece(r, c)) { setStatus('La casilla central de tu segunda fila está ocupada. Libérala antes de invocar el peus.'); return; }
    state.reserve[state.turn]--; addPiece(state.turn, 'peus', r, c); state.history.push({ color: state.turn, text: 'Invoca peus' }); $('respawn-modal').hidden = true; state.selected = null; state.targets = []; finishTurn();
  }

