 else if(p.type==='thyra'||p.type==='basileus'){let max=p.type==='basileus'?1:3;for(let dr=-max;dr<=max;dr++)for(let dc=-max;dc<=max;dc++)if(dr||dc)add(p.r+dr,p.c+dc,{ray:true})}
 else{let dirs=[];if(p.type!=='toxot')dirs.push([0,1],[0,-1],[1,0],[-1,0]);if(p.type!=='pyrgos')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dr,dc]of dirs)for(let n=1;n<15;n++){let r=p.r+dr*n,c=p.c+dc*n;if(!valid(r,c)||!clearPath(p,{r,c}))break;add(r,c,{ray:true});if(occupied(r,c))break}}
 return [...out.values()]}
