function draw(){board.innerHTML='';let defs=svg('defs'),filter=svg('filter',{id:'shadow',x:'-50%',y:'-50%',width:'200%',height:'200%'});filter.append(svg('feDropShadow',{dx:'0',dy:'3',stdDeviation:'2','flood-color':'#080e0f','flood-opacity':'.65'}));defs.append(filter);
 for(let[col,id,top,bot]of[['white','white-grad','#f4f1e4','#c6d0c0'],['black','black-grad','#687d79','#304341']]){let g=svg('linearGradient',{id,x1:'0',y1:'0',x2:'0',y2:'1'});g.append(svg('stop',{offset:'0%', 'stop-color':top}),svg('stop',{offset:'100%','stop-color':bot}));defs.append(g)}board.append(defs);
 for(let r=0;r<15;r++)for(let c=0;c<lengths[r];c++){let{x,y}=center(r,c),p=occupied(r,c),selected=S.selected?.r===r&&S.selected?.c===c,target=S.targets.some(t=>t.r===r&&t.c===c);let shade=(r+c)%2?'#34494a':'#2c4143';let tile=svg('polygon',{points:`${x},${y-27} ${x+40},${y} ${x},${y+27} ${x-40},${y}`,fill:selected?'#426356':shade,stroke:'#536460','stroke-width':'.9',class:`cell${selected?' selected':''}${target?' move-target':''}`,'data-r':r,'data-c':c,role:'gridcell',tabindex:'0','aria-label':`Fila ${r+1}, casilla ${c+1}${p?`, ${names[p.type]} ${p.color==='white'?'blanca':'negra'}`:''}`});board.append(tile);if(target)board.append(svg('circle',{cx:x,cy:y,r:occupied(r,c)?18:5.5,fill:occupied(r,c)?'none':'#b3e4c4',stroke:occupied(r,c)?'#e5b878':'none','stroke-width':2,opacity:'.85','pointer-events':'none'}))}
