 syncUi()}

function syncUi(){ $('turn-label').textContent=S.turn==='white'?'BLANCAS':'NEGRAS';$('turn-dot').style.background=S.turn==='white'?'#b7dec3':'#748a84';let index=String(Math.floor(S.history.length/2)+1).padStart(2,'0');$('move-number').textContent=index;$('turn-index').textContent=index;$('player-name').textContent=S.turn==='white'?'Blancas':'Negras';$('player-subtitle').textContent=S.gameOver?'Partida finalizada':'Tu turno';$('player-piece').textContent=S.turn==='white'?'W':'N';$('player-piece').classList.toggle('black',S.turn==='black');$('white-count').textContent=S.pieces.filter(p=>p.color==='white').length;$('black-count').textContent=S.pieces.filter(p=>p.color==='black').length;$('undo-button').disabled=!S.undo.length;$('game-state').textContent=S.gameOver?'FINALIZADA':'EN CURSO';$('history-count').textContent=`${S.history.length} ${S.history.length===1?'JUGADA':'JUGADAS'}`;let list=$('move-history');list.innerHTML='';if(!S.history.length){let li=document.createElement('li');li.className='empty-history';li.textContent='La partida comienza aquí.';list.append(li)}else for(let i=0;i<S.history.length;i+=2){let li=document.createElement('li'),n=document.createElement('span');n.className='move-number';n.textContent=`${String(Math.floor(i/2)+1).padStart(2,'0')}.`;li.append(n);for(let m of[S.history[i],S.history[i+1]]){let e=document.createElement('span');e.className='move-entry';e.textContent=m?`${m.color==='white'?'○':'●'} ${m.text}`:'';li.append(e)}list.append(li)}}
