 if(p.type==='haplos'&&((p.color==='white'&&r===0)||(p.color==='black'&&r===14))){S.promotion=p.id;draw();promotion();return}finish(king)}
function promotion(){let modal=$('promotion-modal'),options=$('promotion-options');options.innerHTML='';for(let type of['pyrgos','thyra','toxot','anax','basileus','kleido','peus']){let b=document.createElement('button');b.className='promotion-choice';b.innerHTML=`<strong>${marks[type]}</strong><small>${names[type]}</small>`;b.onclick=()=>{let p=S.pieces.find(x=>x.id===S.promotion);if(!p)return;p.type=type;S.history.at(-1).text=`${names[type]} (ascenso)`;S.promotion=null;modal.hidden=true;finish()};options.append(b)}modal.hidden=false}
