board.addEventListener('click',e=>{let cell=e.target.closest('.cell');if(!cell||S.gameOver||S.promotion)return;let r=+cell.dataset.r,c=+cell.dataset.c,p=occupied(r,c);if(S.selected&&S.targets.some(t=>t.r===r&&t.c===c)){moveTo(r,c);return}if(p?.color===S.turn){select(p);return}if(S.selected){S.selected=null;S.targets=[];draw();status('Elige una ficha para ver sus movimientos.')}});
board.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
