$('reset-button').addEventListener('click',()=>{if(S.history.length&&!confirm('¿Empezar una nueva partida? Se perderá el progreso actual.'))return;reset()});$('undo-button').addEventListener('click',()=>{let raw=S.undo.pop();if(raw)restore(raw)});
