(() => {
'use strict';
const NS='http://www.w3.org/2000/svg', lengths=Array.from({length:15},(_,r)=>r%2?7:8);
const names={haplos:'Haplós',kleido:'Kleido',hipeus:'Hipeus',peus:'Peus',pyrgos:'Pyrgos',thyra:'Thyra',toxot:'Toxot',anax:'Anax',basileus:'Basileo'};
const marks={haplos:'H',kleido:'K',hipeus:'I',peus:'P',pyrgos:'R',thyra:'T',toxot:'X',anax:'A',basileus:'B'};
const $=id=>document.getElementById(id),board=$('board'),key=(r,c)=>`${r},${c}`;
const S={pieces:[],turn:'white',selected:null,targets:[],history:[],snapshots:[],reps:new Map(),reserve:{white:0,black:0},gameOver:false,undo:[],promotion:null};
const occupied=(r,c)=>S.pieces.find(p=>p.r===r&&p.c===c),valid=(r,c)=>r>=0&&r<15&&c>=0&&c<lengths[r];
const svg=(tag,attrs={})=>{const el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el};
function put(color,type,r,c){S.pieces.push({id:`${color}-${type}-${r}-${c}-${Math.random().toString(36).slice(2,6)}`,color,type,r,c,moved:false})}
function signature(){return S.pieces.map(p=>`${p.color[0]}${p.type[0]}${p.r}${p.c}`).sort().join('|')+`:${S.turn}:${S.reserve.white}${S.reserve.black}`}
function reset(){S.pieces=[];S.turn='white';S.selected=null;S.targets=[];S.history=[];S.snapshots=[];S.reps.clear();S.reserve={white:0,black:0};S.gameOver=false;S.undo=[];S.promotion=null;
 const back=['pyrgos','thyra','toxot','basileus','anax','toxot','thyra','pyrgos'];
 back.forEach((t,c)=>put('black',t,0,c));[0,2,4,6].forEach(c=>put('black','kleido',1,c));[1,5].forEach(c=>put('black','hipeus',1,c));for(let c=0;c<8;c++)put('black','haplos',2,c);
 for(let c=0;c<8;c++)put('white','haplos',12,c);[0,2,4,6].forEach(c=>put('white','kleido',13,c));[1,5].forEach(c=>put('white','hipeus',13,c));back.forEach((t,c)=>put('white',t,14,c));recordPosition();draw();status('Elige una ficha para ver sus movimientos.')}
function recordPosition(){let sig=signature();S.snapshots.push(sig);S.reps.set(sig,(S.reps.get(sig)||0)+1)}
function center(r,c){return{x:80+c*80+(8-lengths[r])*40,y:38+r*48.5}}
